    let text: string | undefined;
    const read = async () => {
        if (text !== undefined)
            return text;
        const reader = response.body?.getReader();
        const chunks: Uint8Array[] = [];
        let size = 0;
        if (reader)
            while (true) {
                const part = await reader.read().catch(error => {
                    if (signal.aborted) throw new ObservationLookupError('space-lookup-timeout');
                    throw error;
